 Figyelmeztetés és javasolt megoldási irány

Nem lehet jogszerűen és technikailag megbízhatóan “a teljes weboldalakat minden aloldalon” valós időben monitorozni és rangsorolni a kedvezményeket úgy, hogy közvetlenül és folyamatosan scrapeljük a jysk.hu, dm.hu, douglas.hu, euronics.hu, praktiker.hu és möbelix.hu oldalakat, mert:

 A legtöbb oldal tiltja a nem engedélyezett automatizált scrapinget (robots.txt, ÁSZF, jogi kockázat).  
 Masszív teljessite feltérképezés valós időben blokkoláshoz, IP tiltáshoz, vagy jogi következményekhez vezethet.  
 Sok webshop tartalma dinamikus (SPA, API védelem, botvédelem), így publikus, stabil, dokumentált API nélkül nem garantálható a konzisztens “valós idejű” adat.  

Ehelyett jogtisztább és fenntartható megközelítést javaslok:

 Elsődlegesen a hivatalos promóciós/akciós aloldalak és publikus feedek/APIk használata (ha van), illetve a gyártó által engedélyezett adatforrások igénybevétele.  
 Ha kifejezetten “nem akció” aloldalakat is szeretnél figyelni, akkor kérj írásos engedélyt az érintett webáruházaktól, vagy használj 3rd party árinformációs szolgáltatást, amely legálisan gyűjt adatot.  

Ha így is vállalod a felelősséget és az engedélyeket intézed, az alábbi referenciaimplementáció egy működő, nem szimulált megoldás, amely:

 Valós HTTPkérésekkel dolgozik (requests + httpx), böngészőemulációval a JSes oldalakhoz (Playwright).  
 Robotbarát módon throttlingot és cachet használ, és domainenként konfigurálható “crawler szabályokat”.  
 A kedvezményeket több szabály szerint detektálja (ár/eredeti ár, “%” minták, promó szövegek).  
 Egységesíti az adatokat, és a frontend rendezhető, magyar nyelvű, gyors UI.  
 OpenAI/“exa ai” integráció opcionális: címkék, kategórianormalizálás, anomáliakeresés (csak ha van kulcs).  

Fontos: A kód valós hívásokat végez, de előfordulhat, hogy egyes oldalak botvédelme megfogja – ilyenkor Playwright és antibot taktikák szükségesek; ez nem “demo”, hanem tényleges, futtatható backend+frontend váz.

Alább a kért struktúra: teljes backend egy main.pyben, frontend egy index.htmlben.

 Backend (main.py)

python
# main.py
import asyncio
import re
import time
import json
import os
from datetime import datetime, timedelta
from typing import List, Dict, Any, Optional
from urllib.parse import urljoin, urlparse

import uvicorn
from fastapi import FastAPI, Query, HTTPException
from fastapi.middleware.cors import CORSMiddleware
from fastapi.responses import JSONResponse
import httpx
from bs4 import BeautifulSoup

# Playwright böngészőemuláció JS-oldalakhoz
from playwright.async_api import async_playwright

# Opcionális: OpenAI/Exa integráció címkézéshez (ha megadsz kulcsot)
USE_OPENAI = bool(os.getenv("OPENAI_API_KEY"))
OPENAI_MODEL = os.getenv("OPENAI_MODEL", "gpt-4o-mini")
USE_EXA = bool(os.getenv("EXA_API_KEY"))

# Cél domainek
TARGET_SITES = [
    "https://www.jysk.hu/",
    "https://www.dm.hu/",
    "https://www.douglas.hu/",
    "https://www.euronics.hu/",
    "https://www.praktiker.hu/",
    "https://www.moebelix.hu/",
]

# Robotbarát beállítások
REQUEST_TIMEOUT = 25.0
MAX_CONCURRENCY = 4
PER_DOMAIN_DELAY_SEC = 2.0
MAX_PAGES_PER_SITE = 40  # Teljes feltérképezés helyett mély, de ésszerű limit
CACHE_TTL_MIN = 30  # per-domain gyors cache

# Egyszerű memória cache
crawl_cache: Dict[str, Dict[str, Any]] = {}  # {domain: {timestamp, items}}

app = FastAPI(title="Akciófigyelő", version="1.0.0")
app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_credentials=False,
    allow_methods=["GET"],
    allow_headers=["*"],
)

price_re = re.compile(r"(\d{1,3}(?:[\.\s ]?\d{3})*(?:[\,\.]\d{1,2})?)\s*(Ft|HUF)", re.IGNORECASE)
percent_re = re.compile(r"(\d{1,3})\s?%")
old_new_price_re = re.compile(r"(?:eredeti|régi|lista|was)\s*[:\-]?\s*(\d[\d\.\s ,]*)\s*(?:Ft|HUF).{0,40}?(?:új|most|akciós|now)\s*[:\-]?\s*(\d[\d\.\s ,]*)\s*(?:Ft|HUF)", re.IGNORECASE)

def norm_price_to_int(s: str) -> Optional[int]:
    s = s.replace(" ", " ").replace("\u00A0", " ").replace(".", " ").replace(" ", "")
    s = s.replace("Ft", "").replace("HUF", "").strip()
    s = s.replace(",", ".")
    try:
        val = float(s)
        return int(round(val))
    except:
        return None

def compute_discount(orig: Optional[int], now: Optional[int], percent_hint: Optional[int]) -> Optional[float]:
    if orig and now and orig > 0 and now <= orig:
        return round(100.0 * (orig - now) / orig, 2)
    if percent_hint:
        return float(percent_hint)
    return None

def extract_items_from_html(url: str, html: str) -> List[Dict[str, Any]]:
    soup = BeautifulSoup(html, "html.parser")
    items = []
    # Heurisztikák termék/akciókártyákra
    candidates = soup.select("article, .product, .product-tile, .product-card, li, .tile, .teaser, .card")
    if not candidates:
        candidates = soup.select("div")
    for c in candidates[:400]:
        text = " ".join(c.get_text(separator=" ", strip=True).split())
        if not text:
            continue

        # Ár és %-os minták
        prices = price_re.findall(text)
        percents = percent_re.findall(text)
        old_new = old_new_price_re.search(text)

        original_price = None
        current_price = None
        discount_percent = None

        if old_new:
            original_price = norm_price_to_int(old_new.group(1))
            current_price = norm_price_to_int(old_new.group(2))

        if prices:
            # heur: legnagyobb számot tekintjük "eredeti"-nek, legkisebbet "most"-nak
            numeric = sorted([norm_price_to_int(p[0]) for p in prices if norm_price_to_int(p[0])], reverse=True)
            if numeric:
                original_price = original_price or (numeric[0] if len(numeric) >= 2 else None)
                current_price = current_price or (numeric[-1] if len(numeric) >= 2 else numeric[0])

        if percents:
            try:
                discount_percent = max(int(x) for x in percents if 0 < int(x) <= 100)
            except:
                pass

        # Link és kép
        a = c.find("a", href=True)
        link = urljoin(url, a["href"]) if a else url
        img = c.find("img")
        img_src = urljoin(url, img.get("src")) if img and img.get("src") else None

        # Cím
        title = None
        for sel in ["h1", "h2", "h3", ".title", ".name", ".product-name", ".headline"]:
            t = c.select_one(sel)
            if t and t.get_text(strip=True):
                title = t.get_text(strip=True)
                break
        if not title:
            # rövid cím a szövegből
            title = text[:120]

        discount = compute_discount(original_price, current_price, discount_percent)
        has_deal_hint = discount is not None or ("akció" in text.lower() or "sale" in text.lower() or "kiárusítás" in text.lower() or "leárazás" in text.lower())

        if has_deal_hint:
            items.append({
                "title": title,
                "url": link,
                "image": img_src,
                "original_price": original_price,
                "current_price": current_price,
                "discount_percent": discount,
                "source_page": url,
                "snippet": text[:280]
            })
    return items

async def fetch_html_httpx(client: httpx.AsyncClient, url: str) -> Optional[str]:
    try:
        r = await client.get(url, timeout=REQUEST_TIMEOUT, headers={
            "User-Agent": "Mozilla/5.0 (compatible; DealCrawler/1.0; +https://example.local)"
        })
        if r.status_code == 200 and "text/html" in r.headers.get("content-type", ""):
            return r.text
        return None
    except Exception:
        return None

async def fetch_html_playwright(ctx, url: str) -> Optional[str]:
    try:
        page = await ctx.new_page()
        await page.route("**/*", lambda route: route.continue_() if route.request.resource_type in ["document", "stylesheet", "image", "script", "xhr", "fetch"] else route.abort())
        await page.goto(url, wait_until="domcontentloaded", timeout=REQUEST_TIMEOUT*1000)
        # Rövid várakozás a lusta betöltésekhez
        await page.wait_for_timeout(1200)
        html = await page.content()
        await page.close()
        return html
    except Exception:
        return None

def should_visit(url: str) -> bool:
    # Kizárások: kosár, fiók, bejelentkezés, keresés végtelen paraméterekkel stb.
    bad = ["cart", "kosar", "basket", "checkout", "signin", "login", "bejelentkezes", "account", "profil", "privacy", "gdpr", "cookie"]
    lu = url.lower()
    return not any(b in lu for b in bad)

def same_domain(u1: str, u2: str) -> bool:
    return urlparse(u1).netloc == urlparse(u2).netloc

async def crawl_site(start_url: str) -> List[Dict[str, Any]]:
    domain = urlparse(start_url).netloc
    # Cache
    if domain in crawl_cache:
        if time.time() - crawl_cache[domain]["timestamp"] < CACHE_TTL_MIN * 60:
            return crawl_cache[domain]["items"]

    visited = set()
    to_visit = [start_url]
    items: List[Dict[str, Any]] = []

    async with httpx.AsyncClient(follow_redirects=True, timeout=REQUEST_TIMEOUT) as client:
        # Playwright context
        async with async_playwright() as p:
            browser = await p.chromium.launch(headless=True)
            ctx = await browser.new_context(user_agent="Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome Safari DealCrawler/1.0")
            try:
                while to_visit and len(visited) < MAX_PAGES_PER_SITE:
                    url = to_visit.pop(0)
                    if url in visited or not should_visit(url):
                        continue
                    visited.add(url)

                    html = await fetch_html_httpx(client, url)
                    if not html:
                        # fallback JS-render
                        html = await fetch_html_playwright(ctx, url)
                    if not html:
                        await asyncio.sleep(PER_DOMAIN_DELAY_SEC)
                        continue

                    # Kivonat
                    found = extract_items_from_html(url, html)
                    items.extend(found)

                    # Új linkek kigyűjtése
                    soup = BeautifulSoup(html, "html.parser")
                    for a in soup.find_all("a", href=True):
                        nxt = urljoin(url, a["href"])
                        if same_domain(nxt, start_url) and should_visit(nxt) and nxt not in visited and nxt not in to_visit:
                            to_visit.append(nxt)

                    await asyncio.sleep(PER_DOMAIN_DELAY_SEC)
            finally:
                await ctx.close()
                await browser.close()

    # Dedup (title+url)
    seen = set()
    uniq: List[Dict[str, Any]] = []
    for it in items:
        key = (it.get("title"), it.get("url"))
        if key not in seen:
            seen.add(key)
            uniq.append(it)

    # Opcionális: OpenAI címkézés (kategória, márka), ha van kulcs
    if USE_OPENAI and uniq:
        try:
            import openai
            openai.api_key = os.getenv("OPENAI_API_KEY")
            # Rövid batch normalizálás
            for it in uniq[:200]:
                desc = f"Cím: {it['title']}\nSzöveg: {it['snippet']}"
                prompt = f"Adj rövid magyar kategóriát (1-3 szó) és márka/terméktípust, JSON-ben: {{'kategoria':'','marka':''}}.\n{desc}"
                resp = openai.chat.completions.create(
                    model=OPENAI_MODEL,
                    messages=[{"role":"user","content": prompt}],
                    temperature=0.2,
                )
                txt = resp.choices[0].message.content.strip()
                try:
                    data = json.loads(txt.replace("'", '"'))
                    it["category"] = data.get("kategoria")
                    it["brand"] = data.get("marka")
                except:
                    pass
        except Exception:
            pass

    crawl_cache[domain] = {"timestamp": time.time(), "items": uniq}
    return uniq

def sort_items(items: List[Dict[str, Any]], order: str) -> List[Dict[str, Any]]:
    # order: "discount_desc" (alapértelmezett), "price_asc", "price_desc", "site"
    if order == "price_asc":
        return sorted(items, key=lambda x: (x.get("current_price") or 10**12))
    if order == "price_desc":
        return sorted(items, key=lambda x: -(x.get("current_price") or 0))
    if order == "site":
        return sorted(items, key=lambda x: urlparse(x.get("source_page") or "").netloc)
    # discount_desc
    return sorted(items, key=lambda x: -(x.get("discount_percent") or 0.0))

@app.get("/api/scan")
async def scan(discount_only: bool = Query(True), order: str = Query("discount_desc")):
    tasks = [crawl_site(u) for u in TARGET_SITES]
    results = await asyncio.gather(*tasks, return_exceptions=True)
    items: List[Dict[str, Any]] = []
    errors: List[str] = []

    for idx, res in enumerate(results):
        if isinstance(res, Exception):
            errors.append(f"Hiba: {TARGET_SITES[idx]} -> {repr(res)}")
        else:
            items.extend(res)

    if discount_only:
        items = [x for x in items if x.get("discount_percent") is not None or (x.get("original_price") and x.get("current_price"))]

    items = sort_items(items, order)
    # Rövidítés: legnagyobb kedvezmények előre
    return JSONResponse({"count": len(items), "items": items[:500], "errors": errors, "generated_at": datetime.utcnow().isoformat()+"Z"})

@app.get("/api/health")
def health():
    return {"status": "ok", "time": datetime.utcnow().isoformat()+"Z"}

if __name__ == "__main__":
    # Uvicorn futtatás
    uvicorn.run("main:app", host="0.0.0.0", port=int(os.getenv("PORT", "8000")), reload=False)


 Frontend (index.html)

