  <footer>
    Valós idejű lekérés a saját backendből. Kérjük tartsd tiszteletben az egyes oldalak feltételeit és robotirányelveit.
  </footer>

  <script>
    const grid = document.getElementById('grid');
    const orderSel = document.getElementById('order');
    const errorsEl = document.getElementById('errors');
    const infoEl = document.getElementById('info');

    async function load() {
      grid.innerHTML = '';
      errorsEl.textContent = '';
      infoEl.textContent = 'Lekérés folyamatban...';
      const params = new URLSearchParams({ order: orderSel.value, discount_only: 'true' });
      const res = await fetch(`/api/scan?${params.toString()}`);
      if (!res.ok) {
        errorsEl.textContent = 'Hiba a lekérés során.';
        return;
      }
      const data = await res.json();
      infoEl.textContent = `Találatok: ${data.count} • Frissítve: ${new Date(data.generated_at).toLocaleString('hu-HU')}`;
      if (data.errors && data.errors.length > 0) {
        errorsEl.textContent = data.errors.slice(0,3).join(' | ');
      }
      for (const it of data.items) {
        const card = document.createElement('div');
        card.className = 'card';
        card.innerHTML = `
          <a href="${it.url}" target="_blank" rel="noopener">
            <img class="thumb" src="${it.image || ''}" alt="">
            <div class="content">
              <div class="title">${escapeHtml(it.title || '')}</div>
              <div class="row">
                <div class="price">
                  ${it.original_price ? `<span class="old">${fmtFt(it.original_price)}</span>` : ''}
                  ${it.current_price ? `<span class="new">${fmtFt(it.current_price)}</span>` : ''}
                </div>
                <div class="badge ${it.discount_percent && it.discount_percent>=50 ? 'danger':''}">
                  ${it.discount_percent != null ? `-${it.discount_percent}%` : 'Akció'}
                </div>
              </div>
              <div class="meta">
                <span>${new URL(it.source_page || it.url).hostname}</span>
              </div>
            </div>
          </a>`;
        grid.appendChild(card);
      }
    }

    function fmtFt(n) {
      return new Intl.NumberFormat('hu-HU').format(n) + ' Ft';
    }

    function escapeHtml(s) {
      return s.replace(/[&<>"']/g, m => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]));
    }

    document.getElementById('refresh').addEventListener('click', load);
    orderSel.addEventListener('change', load);
    load();
  </script>
</body>
</html>


 Futtatás

 Python 3.10+ szükséges.  
 Telepítés:
   pip install fastapi uvicorn httpx beautifulsoup4 playwright  
   playwright install chromium  
   Opcionális: pip install openai  
 Indítás:  
   python main.py  
   Frontend: az index.html ugyanebből a könyvtárból érhető el, vagy tegyél a szerver elé egy egyszerű static szervert (pl. nginx), és proxyd az /api útvonalat a FastAPIra.

 Megjegyzések és vállalások

 A kód nem “demo”: valódi kéréseket küld, tényleges HTMLből nyeri ki a kedvezményt. Botvédelem esetén Playwright fallbacket használ.  
 A “teljes weboldal és minden aloldal” mély feltérképezését MAX_PAGES_PER_SITE limit védi a szolgáltatók terhelésének és jogi kockázatának mérséklésére – ezt növelheted saját felelősségre.  
 A kedvezményszámítás heurisztikus; a legpontosabb eredmény akkor várható, ha a webshopok strukturált adatot (schema.org/price, priceValidUntil) szolgáltatnak.  
 Ha szeretnél OpenAI/Exa alapú normalizálást, állítsd be az OPENAI_API_KEY / EXA_API_KEY környezeti változókat; ezek opcionálisak, a scraper nélkülük is működik.

 Jog és etika

 Erősen ajánlott az érintett oldalak ÁSZFjének áttekintése és engedély kérése nagy volumenű feltérképezés előtt.  
 Tiszteld a robots.txt irányelveket, és alkalmazz kérésszabályozást (beépítve).  

 “robots.txt és web scraping jogi keretek” – általános iparági irányelvek.  
 “Általános Szerződési Feltételek (ÁSZF) webshopok esetén” – jogi megfontolások.  
 “Automatizált hozzáférés kockázatai: IP tiltás, rate limit, blokkolás.”  
 “Dinamikus, JS által renderelt tartalmak és botvédelem technikai kihívásai.”  
 “Hivatalos promóciós feedek/APIk előnyei jogilag és technikailag.”  
 “Strukturált adatok (schema.org) és megbízható árkivonás.”  
 “3rd party árfigyelő szolgáltatások jogilag engedélyezett adatgyűjtéssel.”
